contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function performing the property-based test
    // take one arbitrary boolean parameter so the checker treats this as ranged input
    function run(bool flip) public payable {
        require(true);

        // Make the state-changing call as a top-level statement and capture whether it reverted.
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: for every input (here `flip`), either the call reverted or C's balance is zero afterwards.
        // The parameter `flip` is unused in the interactions but ensures the function is parameterized as required.
        assert(reverted || address(c).balance == 0);
    }

    receive() external payable {}
}

